// @pit: {"label": "Apply version bump and changelog entries for 0.37.0"}
async ({ workspace: { read, edit } }, p: { added: string; changed: string; fixed: string }) => {
  const rev = async (f: string) => (await read(f, { limit: 1 })).revision;
  const r = (s: string, content: string) => ({ kind: "replace" as const, start: s as `${number}:${string}`, content });
  const v = '  "version": "0.37.0",';
  await edit("CHANGELOG.md", { revision: await rev("CHANGELOG.md"), changes: [
    { kind: "replace", start: "5:HaQuG", content: "## [Unreleased]\n\n## [0.37.0] - 2026-11-15" },
    { kind: "insertAfter", anchor: "12:w-jL0", content: p.added },
    { kind: "insertAfter", anchor: "18:6YIMy", content: p.changed + "\n\n### Fixed\n\n" + p.fixed },
  ] });
  await edit("package.json", { revision: await rev("package.json"), changes: [r("3:wy_Sp", v)] });
  await edit("package-lock.json", { revision: await rev("package-lock.json"), changes: [r("3:wy_Sp", v), r("9:7c_Tk", "    " + v)] });
  await edit("README.md", { revision: await rev("README.md"), changes: [r("53:L01QS", "Run `/reload` after updating. Prefer a fixed release? Use `pi install git:github.com/cv/pit@v0.37.0` instead; package updates won't move a pinned install.")] });
  return (await read("CHANGELOG.md", { limit: 30, format: "raw" })).content;
}
